PRESERVED_DUMP_PROGRAM_CASES_BY_ID = {
    case.case_id: case for case in PRESERVED_DUMP_PROGRAM_CASES
}


def preserved_dump_program_cases() -> tuple[PreservedDumpProgramCase, ...]:
    """Returns the curated preserved JAX dump program cases."""

    return PRESERVED_DUMP_PROGRAM_CASES


def preserved_dump_program_case_by_id(case_id: str) -> PreservedDumpProgramCase:
    """Returns one curated preserved JAX dump program case by ID."""

    try:
        return PRESERVED_DUMP_PROGRAM_CASES_BY_ID[case_id]
    except KeyError as error:
        available_case_ids = ", ".join(case.case_id for case in PRESERVED_DUMP_PROGRAM_CASES)
        raise ValueError(
            f"unknown preserved dump program case '{case_id}'; available cases: {available_case_ids}"
        ) from error


__all__ = [
    "PRESERVED_DUMP_PROGRAM_CASES",
    "PreservedDumpProgramCase",
    "preserved_dump_program_case_by_id",
    "preserved_dump_program_cases",
]
